use anyhow::{Result,bail};
use image::RgbaImage;
use std::{mem::size_of,ffi::c_void};
use windows::Win32::{Foundation::{COLORREF,RECT},Graphics::Gdi::*};
#[derive(Clone,Copy)]pub struct Content{pub combat:CombatContent,pub scores:[u32;2],pub tick:f64,pub health:[[f32;5];2],pub show_intro:bool,pub adjustment:Option<(f32,f32,f32,f32)>}
pub fn visible_height(combat:bool,intro:bool,adjustment:bool)->u32{(if combat{224}else{176})+if intro{56}else{0}+if adjustment{32}else{0}}
pub struct Hud{pub width:u32,pub height:u32,scale:usize,dc:HDC,bitmap:HBITMAP,font:HFONT,big:HFONT,old:HGDIOBJ,medium:HFONT,metric:HFONT,resources:CombatResources,bits:*mut u8,pixels:Vec<u8>,portraits:[Vec<RgbaImage>;2]}
fn fill_scaled(data:&mut[u8],x:i32,y:i32,w:i32,h:i32,color:[u8;4],scale:i32){let width=1024*scale;let height=CANVAS_HEIGHT as i32*scale;for yy in (y*scale).max(0)..((y+h)*scale).min(height){for xx in (x*scale).max(0)..((x+w)*scale).min(width){let i=(yy as usize*width as usize+xx as usize)*4;data[i..i+4].copy_from_slice(&[color[2],color[1],color[0],color[3]]);}}}
impl Hud{
 pub fn take_pixels(&mut self)->Vec<u8>{std::mem::take(&mut self.pixels)}
 pub fn replace_pixels(&mut self,mut pixels:Vec<u8>){pixels.resize((self.width*self.height*4)as usize,0);self.pixels=pixels;}
 pub fn new(portraits:&[Vec<RgbaImage>;2])->Result<Self>{unsafe{let width=crate::settings::Settings::load()?.hud_width;let scale=width as usize/1024;let height=CANVAS_HEIGHT*scale as u32;let dc=CreateCompatibleDC(None);if dc.is_invalid(){bail!("HUD 메모리 DC 생성 실패");}let info=BITMAPINFO{bmiHeader:BITMAPINFOHEADER{biSize:size_of::<BITMAPINFOHEADER>()as u32,biWidth:width as i32,biHeight:-(height as i32),biPlanes:1,biBitCount:32,biCompression:BI_RGB.0,..Default::default()},..Default::default()};let mut bits:*mut c_void=std::ptr::null_mut();let bitmap=CreateDIBSection(Some(dc),&info,DIB_RGB_COLORS,&mut bits,None,0)?;let old=SelectObject(dc,HGDIOBJ(bitmap.0));let make_font=|height:i32|{let mut lf=LOGFONTW{lfHeight:-height*scale as i32,lfWeight:FW_MEDIUM.0 as i32,lfQuality:ANTIALIASED_QUALITY,..Default::default()};for(i,c)in "Malgun Gothic".encode_utf16().enumerate(){lf.lfFaceName[i]=c;}CreateFontIndirectW(&lf)};let font=make_font(24);let big=make_font(44);let medium=make_font(32);let metric=make_font(40);let resources=CombatResources::load()?;SetBkMode(dc,TRANSPARENT);Ok(Self{width,height,scale,dc,bitmap,font,big,old,medium,metric,resources,bits:bits.cast(),pixels:vec![0;(width*height*4)as usize],portraits:portraits.clone()})}}
 unsafe fn text(&self,value:&str,rect:RECT,big:bool,color:u32){let previous=SelectObject(self.dc,HGDIOBJ(if big{self.big.0}else{self.font.0}));SetTextColor(self.dc,COLORREF(color));let mut wide:Vec<u16>=value.encode_utf16().collect();let mut rect=RECT{left:rect.left*self.scale as i32,top:rect.top*self.scale as i32,right:rect.right*self.scale as i32,bottom:rect.bottom*self.scale as i32};DrawTextW(self.dc,&mut wide,&mut rect,DT_CENTER|DT_SINGLELINE|DT_VCENTER|DT_NOPREFIX);SelectObject(self.dc,previous);}
 pub fn render(&mut self,content:&Content)->&[u8]{unsafe{
  let scale=self.scale;let fill=|data:&mut[u8],x,y,w,h,color|fill_scaled(data,x,y,w,h,color,scale as i32);let data=std::slice::from_raw_parts_mut(self.bits,(self.width*self.height*4)as usize);data.fill(0);let compact_height=if content.combat.available{224}else{176};let base_height=visible_height(content.combat.available,content.show_intro,content.adjustment.is_some())as i32;fill(data,0,0,1024,base_height,[18,34,42,255]);
  for team in 0..2{let color=if team==0{[155,211,239,255]}else{[233,164,160,255]};for i in 0..5{let x=32+team as i32*512+i as i32*96;let ratio=content.health[team][i].clamp(0.0,1.0);fill(data,x-2,68,68,68,color);fill(data,x,70,64,64,[29,45,52,255]);if let Some(image)=self.portraits[team].get(i){for y in 0..64*scale{for xx in 0..64*scale{let p=image.get_pixel((xx/scale)as u32,(y/scale)as u32);let k=((y+70*scale)*self.width as usize+x as usize*scale+xx)*4;let alpha=p[3]as f32/255.0;let dim=if ratio>0.0{1.0}else{0.32};for c in 0..3{data[k+c]=(p[2-c]as f32*alpha*dim+data[k+c]as f32*(1.0-alpha))as u8;}}}}fill(data,x,145,64,10,[48,64,69,255]);fill(data,x,145,(64.0*ratio).round()as i32,10,color);}}
  self.text(&format!("파랑 {}",content.scores[0]),RECT{left:16,top:7,right:496,bottom:61},true,0x00efd39b);self.text(&format!("{:02}:{:02}",content.tick as u32/3600,(content.tick as u32/60)%60),RECT{left:400,top:7,right:624,bottom:61},true,0x00e7e9ef);self.text(&format!("{} 빨강",content.scores[1]),RECT{left:528,top:7,right:1008,bottom:61},true,0x00a0a4e9);
  self.render_combat(data,&content.combat);let mut y=compact_height;if content.show_intro{self.text("트리거 짧게 재생/정지 · 길게 잡기 · 양손 크기/회전",RECT{left:8,top:y,right:1016,bottom:y+28},false,0x00d3d5ce);y+=28;self.text("왼스틱 거리/높이 · 오른스틱 회전/크기 · A/X 처음 배치",RECT{left:8,top:y,right:1016,bottom:y+28},false,0x00d3d5ce);y+=28;}if let Some((scale,height,distance,yaw))=content.adjustment{self.text(&format!("크기 {scale:.2} · 거리 {distance:.2}m · 높이 {height:.2}m · 회전 {yaw:.0}°"),RECT{left:8,top:y,right:1016,bottom:y+32},false,0x00b9d3d4);}
  let _=GdiFlush();for y in 0..self.height as usize{for x in 0..self.width as usize{let k=(y*self.width as usize+x)*4;let alpha=if y<base_height as usize*scale||self.combat_alpha(x,y,&content.combat){255}else{0};self.pixels[k..k+4].copy_from_slice(&[data[k+2],data[k+1],data[k],alpha]);}}&self.pixels
 }}
}
impl Drop for Hud{fn drop(&mut self){unsafe{SelectObject(self.dc,self.old);let _=DeleteObject(HGDIOBJ(self.bitmap.0));let _=DeleteObject(HGDIOBJ(self.font.0));let _=DeleteObject(HGDIOBJ(self.big.0));let _=DeleteObject(HGDIOBJ(self.medium.0));let _=DeleteObject(HGDIOBJ(self.metric.0));let _=DeleteDC(self.dc);}}}

include!("combat_hud.rs");
